import json
from pathlib import Path
p = Path('products/services/nlnet-open-call-fit/proposal-link-inventory.json')
data = json.loads(p.read_text())
if isinstance(data, dict):
    print('Inventory keys:', sorted(data))
    entries = next((data[k] for k in ('links', 'entries', 'anchors') if isinstance(data.get(k), list)), None)
else:
    entries = data if isinstance(data, list) else None
if entries is None:
    print(json.dumps(data, ensure_ascii=True)[:4500])
else:
    for entry in entries[:80]:
        row = json.dumps(entry, ensure_ascii=True)
        if any(term in row.lower() for term in ('call', 'eligib', 'payment', 'milestone', 'grant', 'fund', 'terms', 'faq', 'licen', 'deadline')):
            print(row[:500])
